from pathlib import Path
import hashlib
root=Path(__file__).resolve().parents[1]
changes=[{'path': 'tools/test-ui-sumatra.ps1', 'before_sha256': 'fe3a07f02f8a14caf1fe12ff148b9f7056727db9d794475c215c8a83a8299a07', 'after_sha256': '589128cb6de43f65da2ae8d7c2dab6ceb4c75aff9a001d1dc162a587503af3e6', 'replacements': [('param([string]$BuildReceipt=$env:DCM_BUILD_RECEIPT,[string]$Runtime=$env:DCM_SUMATRA_SOURCE_EXE,[switch]$ResizeTiming)\n', 'param([string]$BuildReceipt=$env:DCM_BUILD_RECEIPT,[string]$Runtime=$env:DCM_SUMATRA_SOURCE_EXE,[switch]$ResizeTiming,[switch]$CompactLabels)\n'), ("$receipt['resize_layout_checks']=$layoutChecks\n", "$receipt['resize_layout_checks']=$layoutChecks\n$labelChecks=New-Object 'Collections.Generic.List[object]';$receipt['label_checks']=$labelChecks;$receipt['compact_labels']=[bool]$CompactLabels\n"), ('    $shots.Add([ordered]@{name=$name;path=$s.Path;sha256=(Hash $s.Path);teal=$s.TealSamples;orange=$s.OrangeSamples;visual_reviewed=$false})\n', "    $shots.Add([ordered]@{name=$name;path=$s.Path;sha256=(Hash $s.Path);teal=$s.TealSamples;orange=$s.OrangeSamples;visual_reviewed=$false})\n    if($CompactLabels -and $name -ne 'failure'){\n        $labels=[DcmLabelProbe]::Check($hwnd,$app.Id);$labelChecks.Add([ordered]@{name=$name;audit=$labels})\n        Json (Join-Path $lab ($name+'-labels.json')) $labels\n        if(-not $labels.Passed){throw ('COMPACT_LABELS: '+($labels.Errors -join '; '))}\n    }\n"), ("    Add-Type -Path (Join-Path $repo 'tests/native/dcm-native.cs') -ReferencedAssemblies @('System.dll','System.Core.dll','System.Drawing.dll')\n", "    Add-Type -Path (Join-Path $repo 'tests/native/dcm-native.cs') -ReferencedAssemblies @('System.dll','System.Core.dll','System.Drawing.dll')\n    if($CompactLabels){Add-Type -Path (Join-Path $repo 'tests/native/dcm-label-probe.cs') -ReferencedAssemblies @('System.dll','System.Core.dll','System.Drawing.dll')}\n"), ("    [DcmSumatraProbe]::SetEdit($hwnd,$app.Id,1003,'Accepted')\n", "    [DcmSumatraProbe]::SetEdit($hwnd,$app.Id,1003,'Accepted')\n    if($CompactLabels){[DcmLabelProbe]::LongSort($hwnd,$app.Id);Start-Sleep -Milliseconds 300}\n"), ("    if($layoutFailures.Count){throw ($layoutFailures -join '; ')}\n", "    if($layoutFailures.Count){throw ($layoutFailures -join '; ')}\n    if($CompactLabels){AddPass 'all-audited-labels-and-selected-values-fit-without-overlap'}\n")]}, {'path': 'tools/flowdev-dcm/config/checks.json', 'before_sha256': 'bdfba19a6dda6d97843609057ddccb01dd8a033ce647215225ad0f4a9aa47371', 'after_sha256': 'ad04316077f852584095b451bf6ba0a1f2ac47d240f1cd70beac01eb11a4b36f', 'replacements': [('        "ui-sumatra-resize-timing": ["powershell.exe", "-NoProfile", "-NonInteractive", "-File", "tools/test-ui-sumatra.ps1", "-ResizeTiming"],\n', '        "ui-sumatra-resize-timing": ["powershell.exe", "-NoProfile", "-NonInteractive", "-File", "tools/test-ui-sumatra.ps1", "-ResizeTiming"],\n        "ui-compact-labels": ["powershell.exe", "-NoProfile", "-NonInteractive", "-File", "tools/test-ui-sumatra.ps1", "-CompactLabels"],\n')]}, {'path': 'tools/test-ui-tooling.ps1', 'before_sha256': 'ffcb16d48fe4a5f248620a62baa180317fe7779f781ff8198db2f38e1a0df350', 'after_sha256': 'ec49df69aa3b121aaf39c39251ff72b877208543a8ba7cb8a4bb2dd92b14ad62', 'replacements': [("    $receipt['scroll_probe_compiled']=$true\n", "    $receipt['scroll_probe_compiled']=$true\n    Add-Type -Path (Join-Path $repo 'tests/native/dcm-label-probe.cs') -ReferencedAssemblies @('System.dll','System.Core.dll','System.Drawing.dll')\n    $receipt['label_probe_compiled']=$true\n")]}]
for spec in changes:
 p=root/spec['path']; b=p.read_bytes()
 assert hashlib.sha256(b).hexdigest()==spec['before_sha256'],(p,'input changed')
 s=b.decode()
 for old,new in spec['replacements']:
  assert s.count(old)==1,(p,'replacement not unique')
  s=s.replace(old,new)
 assert hashlib.sha256(s.encode()).hexdigest()==spec['after_sha256'],(p,'output changed')
 p.write_bytes(s.encode())
print('Exact compact-label test wiring verified')
